// Pack named bit fields into one integer, parsing a tiny spec language.
// spec is a comma-separated list of fields (the empty string is zero fields).
// A field is one of:
//   name:width=value   a field width bits wide holding value
//   name               a 1-bit flag set to 1 (same as name:1=1)
//   !name              a 1-bit flag set to 0 (same as name:1=0)
// name is one or more of the characters a-z and _, and names must be distinct.
// width is a decimal integer from 1 to 32 with no leading zeros. value is
// decimal with no leading zeros (except the single digit 0), or 0x followed by
// one or more hex digits (0-9, a-f, A-F), or 0b followed by one or more binary
// digits; leading zeros after 0x or 0b are allowed. value must be less than
// 2 to the power width. Fields are packed from the least significant bit: the
// first field takes the lowest width bits, the next field the bits just above
// it, and so on; the total width must be at most 62.
// Return the packed integer, or -1 if spec breaks any rule (spaces, empty
// fields, signs, other characters in names, duplicate names, a value that does
// not fit its width, a total width above 62, ...).
// Examples:
//   pack_fields("mode:3=5,on,!dbg,level:4=0xA") == 333
//   pack_fields("a:2=4") == -1
fn pack_fields(spec: Str) -> Int {
  if spec == "" {
    return 0;
  }
  let mut seen: List[Str] = [];
  let mut total = 0;
  let mut shift = 0;
  for field in split(spec, ",") {
    let mut name = field;
    let mut width = 1;
    let mut value = 1;
    match split_once(field, "=") {
      Some((left, right)) => {
        match split_once(left, ":") {
          Some((nm, w)) => {
            name = nm;
            width = parse_digits(w, 10, 33, false);
            if width < 1 {
              return -1;
            }
            value = parse_value(right, pow(2, width));
          },
          None => { return -1; },
        }
      },
      None => {
        if starts_with(field, "!") {
          name = substr(field, 1, str_len(field));
          value = 0;
        }
      },
    }
    if value < 0 || !valid_name(name) || contains(seen, name) {
      return -1;
    }
    seen = push(seen, name);
    if shift + width > 62 {
      return -1;
    }
    total = total + value * pow(2, shift);
    shift = shift + width;
  }
  total
}

fn valid_name(name: Str) -> Bool {
  name != "" && all(chars(name), |c| is_lower(c) || c == "_")
}

fn parse_value(s: Str, limit: Int) -> Int {
  if starts_with(s, "0x") {
    parse_digits(substr(s, 2, str_len(s)), 16, limit, true)
  } else if starts_with(s, "0b") {
    parse_digits(substr(s, 2, str_len(s)), 2, limit, true)
  } else {
    parse_digits(s, 10, limit, false)
  }
}

// Value of s in base, or -1 if s is empty, has a bad digit, a forbidden
// leading zero, or a value >= limit.
fn parse_digits(s: Str, base: Int, limit: Int, zeros_ok: Bool) -> Int {
  let cs = chars(s);
  if len(cs) == 0 || (!zeros_ok && len(cs) > 1 && cs[0] == "0") {
    return -1;
  }
  let ds = take(chars("0123456789abcdef"), base);
  let mut v = 0;
  for c in cs {
    match index_of(ds, to_lower(c)) {
      Some(d) => { v = v * base + d; },
      None => { return -1; },
    }
    if v >= limit {
      return -1;
    }
  }
  v
}
